--
-- Name: bulk_update_stats(public.update_batting_stats_input[], public.update_fielding_stats_input[], public.update_pitching_stats_input[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.bulk_update_stats(batting_stats public.update_batting_stats_input[], fielding_stats public.update_fielding_stats_input[], pitching_stats public.update_pitching_stats_input[]) RETURNS SETOF public.players
    LANGUAGE plpgsql STRICT
    AS $$
BEGIN

    PERFORM upsert_type_into_table('update_batting_stats_input', 'player_id', 'career_batting', batting_stats);

    PERFORM upsert_type_into_table('update_fielding_stats_input', 'player_id', 'career_fielding', fielding_stats);

    PERFORM upsert_type_into_table('update_pitching_stats_input', 'player_id', 'career_pitching', pitching_stats);


    RETURN QUERY
        SELECT * from players WHERE id IN (SELECT player_id
                                                  FROM UNNEST(batting_stats)
                                                  UNION
                                                  SELECT player_id
                                                  FROM UNNEST(pitching_stats)
                                                  UNION
                                                  SELECT player_id
                                                  FROM UNNEST(fielding_stats));

END;
$$;


ALTER FUNCTION public.bulk_update_stats(batting_stats public.update_batting_stats_input[], fielding_stats public.update_fielding_stats_input[], pitching_stats public.update_pitching_stats_input[]) OWNER TO postgres;

