--

CREATE FUNCTION public.get_columns_for_type(type_name text) RETURNS SETOF pg_attribute
    LANGUAGE sql STABLE STRICT
    AS $$
SELECT *
FROM pg_attribute
WHERE attrelid = (SELECT typrelid
                  FROM pg_type
                  WHERE typname = type_name)
  AND attnum > 0
  AND NOT attisdropped
    ;

$$;


