--
-- Name: get_field_value(anyelement, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_field_value(p_record anyelement, field_name text) RETURNS text
    LANGUAGE plpgsql
    AS $_$
DECLARE
    result TEXT;
BEGIN
    EXECUTE format(
        'SELECT $1.%I',
        field_name
    ) INTO result
    USING p_record;

    RETURN result;
EXCEPTION
    WHEN others THEN
        RAISE EXCEPTION 'Field "%" does not exist in the record type', field_name;
END;
$_$;


ALTER FUNCTION public.get_field_value(p_record anyelement, field_name text) OWNER TO postgres;

--
-- Name: get_field_value(anyrange, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_field_value(p_record anyrange, field_name text) RETURNS text
    LANGUAGE plpgsql
    AS $_$
DECLARE
    result TEXT;
BEGIN
    EXECUTE format(
            'SELECT $1.%I FROM (VALUES (ROW($1))) AS sub($1) LIMIT 1',
            field_name
            )
        USING p_record
        INTO result;

    RETURN result;
EXCEPTION
    WHEN others THEN
        RAISE EXCEPTION 'Field "%" does not exist in the record type', field_name;
END;
$_$;


ALTER FUNCTION public.get_field_value(p_record anyrange, field_name text) OWNER TO postgres;

--
-- Name: upsert_type_into_table(text, text, text, anyarray); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.upsert_type_into_table(type_name text, pk_field text, table_name text, input_values anyarray) RETURNS void
    LANGUAGE plpgsql STRICT
    AS $$
DECLARE
    column_list TEXT;
    update_section  TEXT;
    updated_values int[];
BEGIN
    RAISE NOTICE '%s', input_values;

    IF cardinality(input_values) = 0 THEN
        RETURN;
    END IF;

    RAISE NOTICE 'Get attributes for type %s', type_name;
    select string_agg(format('"%s"', attname), ', ')
    INTO column_list
    FROM get_columns_for_type(type_name);

    RAISE NOTICE 'Get values for %s', type_name;
    select string_agg(format('"%s"=EXCLUDED."%s"', attname, attname), ', ')
    INTO update_section
    FROM get_columns_for_type(type_name)
    WHERE attname != pk_field;

    EXECUTE format(
            'INSERT INTO %s (%s) SELECT %s from UNNEST(Array[%L::%s[]]) ON CONFLICT (player_id) DO UPDATE SET %s',
            table_name,
            column_list,
            column_list,
            input_values,
            type_name,
            update_section);
END
$$;


ALTER FUNCTION public.upsert_type_into_table(type_name text, pk_field text, table_name text, input_values anyarray) OWNER TO postgres;

