--
-- Name: career_batting; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.career_batting AS
 SELECT player_id,
    sum(g) AS g,
    sum(pa) AS pa,
    sum(ab) AS ab,
    sum(r) AS r,
    sum(h) AS h,
    sum(doubles) AS doubles,
    sum(triples) AS triples,
    sum(hr) AS hr,
    sum(rbi) AS rbi,
    sum(sb) AS sb,
    sum(cs) AS cs,
    sum(bb) AS bb,
    sum(so) AS so,
    sum(tb) AS tb,
    sum(gidp) AS gidp,
    sum(hbp) AS hbp,
    sum(sh) AS sh,
    sum(ibb) AS ibb
   FROM public.season_batting
  WHERE (( SELECT count(1) AS count
           FROM regexp_split_to_table((season_batting.lg_id)::text, ','::text) regexp_split_to_table(regexp_split_to_table)
          WHERE ((season_batting.lg_id)::text = ANY ((ARRAY['AL'::character varying, 'NL'::character varying])::text[]))) > 0)
  GROUP BY player_id;


